{"content":"function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function isPrimitive(value) {
  return value === null
    || typeof value === 'string'
    || typeof value === 'number'
    || typeof value === 'boolean';
}

function isNestedObject(value) {
  if (!isPlainObject(value)) {
    return false;
  }
  for (const key of Object.keys(value)) {
    if (!isPrimitive(value[key])) {
      return false;
    }
  }
  return true;
}

function assertConfig(value, name) {
  if (!isPlainObject(value)) {
    throw new TypeError(`${name} must be a non-null, non-array plain object`);
  }
}

// Define an own enumerable data property, so keys like "__proto__" are
// treated as ordinary data keys rather than triggering the prototype setter.
function setKey(target, key, value) {
  Object.defineProperty(target, key, {
    value,
    writable: true,
    enumerable: true,
    configurable: true,
  });
}

function copyNested(source) {
  const result = {};
  for (const key of Object.keys(source)) {
    setKey(result, key, source[key]);
  }
  return result;
}

export function mergeConfig(defaults, overrides = {}) {
  assertConfig(defaults, 'defaults');
  assertConfig(overrides, 'overrides');

  const result = {};

  for (const key of Object.keys(defaults)) {
    const value = defaults[key];
    if (isNestedObject(value)) {
      setKey(result, key, copyNested(value));
    } else {
      setKey(result, key, value);
    }
  }

  for (const key of Object.keys(overrides)) {
    const overrideValue = overrides[key];
    const hasDefault = Object.prototype.hasOwnProperty.call(result, key);
    const defaultValue = hasDefault ? result[key] : undefined;

    if (isNestedObject(overrideValue) && hasDefault && isNestedObject(defaultValue)) {
      const merged = copyNested(defaultValue);
      for (const nestedKey of Object.keys(overrideValue)) {
        setKey(merged, nestedKey, overrideValue[nestedKey]);
      }
      setKey(result, key, merged);
    } else if (isNestedObject(overrideValue)) {
      setKey(result, key, copyNested(overrideValue));
    } else {
      setKey(result, key, overrideValue);
    }
  }

  return result;
}
